test('open ShadowRoot fixture preserves Bilibili component public backing fields', async () => {
  await withDocument('<title>Shadow fixture</title><bili-comments></bili-comments>', async () => {
    Object.assign(document.defaultView!, {__INITIAL_STATE__: {videoData: {pubdate: 1791967296}}});
    const list = document.querySelector('bili-comments')!.attachShadow({mode: 'open'});
    const host = document.createElement('bili-comment-renderer');
    Object.assign(host, {__data: {rpid_str: '9007199254740993', member: {mid: '88', uname: 'Shadow author'}, ctime: 1791849600, like: 4}});
    list.append(host);
    const root = host.attachShadow({mode: 'open'});
    const rich = document.createElement('bili-rich-text');
    root.append(rich);
    rich.attachShadow({mode: 'open'}).innerHTML = '<span id="contents">有原因的玩家反馈</span>';
    const data = await readContentPage();
    assert.equal(data.comments.length, 1);
    assert.equal(data.comments[0].sourceRecordId, '9007199254740993');
    assert.equal(data.comments[0].authorName, 'Shadow author');
    assert.equal(data.comments[0].publishedAtEpochSeconds, 1791849600);
    assert.equal(data.publishedAtEpochSeconds, 1791967296);
  });
});

// Keys and mixin key from Bilibili's published WBI example; the signature is checked with Node's own MD5.
const wbiImgUrls = 'https://i0.hdslb.com/bfs/wbi/7cd084941338484aae1ad9425b84077c.png-https://i0.hdslb.com/bfs/wbi/4932caff0ff746eab6f01bf08b70ac45.png';
const wbiMixinKey = 'ea1db124af3c7062474693fa704f4ff8';
function commentApi(responses: Array<Record<string, unknown>>, options: {cacheKeys?: boolean} = {}) {
  const requests: Array<{url: string; credentials?: string}> = [];
  const install = () => {
    const view = document.defaultView as unknown as Record<string, unknown> & {localStorage: Storage};
    if (options.cacheKeys !== false) view.localStorage.setItem('wbi_img_urls', wbiImgUrls);
    view.fetch = async (url: string, init?: {credentials?: string}) => {
      requests.push({url, credentials: init?.credentials});
      const body = url.includes('/x/web-interface/nav')
        ? {code: -101, data: {wbi_img: {img_url: wbiImgUrls.split('-https://')[0], sub_url: `https://${wbiImgUrls.split('-https://')[1]}`}}}
        : responses.shift() ?? {code: -400};
      return {ok: true, json: async () => body};
    };
  };
  return {requests, install};
}
const apiReply = (rpid: number, text: string, extra: Record<string, unknown> = {}) => ({rpid, rpid_str: String(rpid), parent: 0, root: 0,
  mid: 900 + rpid, member: {mid: String(900 + rpid), uname: `User ${rpid}`}, content: {message: text}, like: rpid, rcount: 0, ctime: 1791849600,
  reply_control: {time_desc: '3天前发布'}, ...extra});

test('comments are read through the signed public comment API without waiting for rendering', async () => {
  await withDocument('<title>API fixture_哔哩哔哩</title><bili-comments></bili-comments>', async () => {
    Object.assign(document.defaultView!, {__INITIAL_STATE__: {videoData: {aid: 113, pubdate: 1791967296}}});
    const api = commentApi([
      {code: 0, data: {top_replies: [apiReply(1, '置顶的版本反馈')],
        replies: [apiReply(2, '技能后摇太长了', {rcount: 1, replies: [apiReply(3, '确实没法反打', {parent: 2, parent_str: '2', root: 2, root_str: '2'})]})],
        cursor: {is_end: false, all_count: 4, pagination_reply: {next_offset: 'next-page-token'}}}},
      {code: 0, data: {replies: [apiReply(4, '第二页的玩家意见')], cursor: {is_end: true, all_count: 4}}}]);
    api.install();
    const started = Date.now();
    const data = await readContentPage();
    assert.ok(Date.now() - started < 2000);
    assert.equal(data.commentState, 'loaded');
    assert.deepEqual(data.comments.map((comment) => comment.sourceRecordId), ['1', '2', '3', '4']);
    assert.deepEqual(data.comments[2], {text: '确实没法反打', authorUid: '903', authorName: 'User 3', authorProfileUrl: 'https://space.bilibili.com/903',
      sourceRecordId: '3', parentSourceRecordId: '2', publishedAtText: '3天前发布', publishedAtEpochSeconds: 1791849600, likes: 3, replies: 0, isReply: true});
    assert.equal(data.comments[1].replies, 1);
    assert.equal(data.comments[1].isReply, false);
    assert.equal(api.requests.length, 2);
    assert.equal(api.requests.every((item) => item.credentials === 'include'), true);
    for (const [index, item] of api.requests.entries()) {
      const url = new URL(item.url);
      assert.equal(url.origin + url.pathname, 'https://api.bilibili.com/x/v2/reply/wbi/main');
      assert.equal(url.searchParams.get('oid'), '113');
      assert.equal(url.searchParams.get('type'), '1');
      assert.equal(url.searchParams.get('mode'), '3');
      assert.equal(url.searchParams.get('pagination_str'), JSON.stringify({offset: index ? 'next-page-token' : ''}));
      const query = item.url.slice(item.url.indexOf('?') + 1, item.url.indexOf('&w_rid='));
      assert.equal(url.searchParams.get('w_rid'), createHash('md5').update(query + wbiMixinKey).digest('hex'));
    }
  });
});

